#include "th10/game/effect_indicator_queue.hpp"
// 0x00419120 - expire queued indicators into one of ten rotating VM slots.
int EffectIndicatorQueue_Drain(EffectIndicatorNode*node,EffectIndicatorState*s,int owner,bool release,const EffectIndicatorOps*o){while(node){EffectIndicatorNode*next=node->next;if(node->owner_tag==0||node->owner_tag==owner)--node->countdown;if(node->countdown>0){node=next;continue;}const int slot=s->slot;if(s->handles[slot])o->retire_handle(o->context,s->handles[slot]);s->handles[slot]=0;node->x+=node->intensity*8.f;int script,alpha;float a,b;if(node->intensity<=1.f){script=slot+2;alpha=15;a=node->intensity;b=node->intensity*1.5f;}else if(node->intensity<=2.f){script=slot+12;alpha=(int)(node->intensity*15.f);a=node->intensity*.5f;b=node->intensity*.75f;}else{script=slot+12;alpha=30;a=node->intensity*.5f;b=node->intensity*.75f;}EffectIndicatorSpawn q=o->spawn(o->context,node,script,alpha,a,b);s->handles[slot]=q.handle;for(int i=0;i<3;++i)s->positions[slot][i]=q.position[i];if(node->anchor_mode==1)s->positions[slot][0]+=node->offset*.5f;else if(node->anchor_mode==2)s->positions[slot][0]-=node->offset*.5f;s->values[slot]=node->offset;o->format_text(o->context,q.handle,node->anchor_mode,node->text);s->slot=(slot+1)%10;if(node->previous)node->previous->next=node->next;if(node->next)node->next->previous=node->previous;node->next=node->previous=0;if(release)o->release_node(o->context,node);node=next;}return 0;}
